st.set_page_config(page_title="Anjana | NMC CCU Interview Guide", page_icon="🫀", layout="wide", initial_sidebar_state="collapsed")
HTML = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Anjana · NMC CCU Interview Guide</title><style>\n:root{--ink:#173b40;--muted:#526c6f;--teal:#096d64;--paper:#f5f8f5;--line:#d2dfd8;--gold:#f4d895}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,-apple-system,sans-serif}button,input,select,textarea{font:inherit}button,a,input,select,summary{touch-action:manipulation}button{cursor:pointer;border:1px solid var(--line);background:white;color:var(--ink);border-radius:10px;padding:10px 15px;min-height:44px}button:hover{border-color:var(--teal)}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #d79823;outline-offset:3px}a{color:#086d62;text-underline-offset:3px}header{background:#143c3d;color:#fff;padding:46px max(24px,calc((100vw - 1120px)/2));border-bottom:6px solid var(--gold)}.eyebrow{font-size:12px;letter-spacing:.18em;font-weight:750;text-transform:uppercase}.overline{color:#b8ded1}h1{font-size:clamp(32px,5vw,54px);line-height:1.13;max-width:800px;margin:16px 0}header p{max-width:780px;color:#dcebe5;margin:16px 0}.badges{display:flex;gap:10px;flex-wrap:wrap}.badge{font-size:13px;padding:7px 12px;border:1px solid #5d8179;border-radius:30px;color:white}.shell{max-width:1168px;margin:auto;padding:22px 24px 50px}nav{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:24px;border-bottom:1px solid var(--line);padding-bottom:18px}nav button{border:0;background:transparent;font-size:14px;font-weight:650}nav button[aria-selected=true],.primary{background:var(--teal);color:white}section[hidden]{display:none}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.triple{grid-template-columns:repeat(3,minmax(0,1fr))}.card{background:white;border:1px solid var(--line);padding:24px;border-radius:18px;min-width:0}.card h2,.card h3{margin-top:0}h2{font-size:26px;line-height:1.25}h3{font-size:19px;line-height:1.35}p{margin:10px 0 16px}.muted,.small{color:var(--muted)}.small{font-size:13px}.note{padding:14px 17px;background:#edf5f0;border-left:4px solid var(--teal);border-radius:8px}.warm{background:#fff7e7;border-color:#d3a64b}.intro{font-size:18px;line-height:1.75}.steps{margin:0;padding-left:23px}.steps li{padding:5px 0}label{display:block}input[type=search],select,textarea{border:1px solid #b7cbc0;background:white;border-radius:10px;padding:11px;color:var(--ink);width:100%}.filters{display:grid;grid-template-columns:2fr 1fr;gap:12px;margin-bottom:16px}details{background:white;border:1px solid var(--line);border-radius:12px;margin:10px 0}summary{padding:17px 20px;cursor:pointer;font-weight:650}details .body{padding:0 20px 20px}details[open] summary{color:var(--teal)}.qnum{color:#6c8582;font-size:12px;margin-right:10px}.answer{white-space:pre-wrap}.review{display:flex;gap:9px;flex-wrap:wrap;align-items:center;margin-top:16px}.review button[aria-pressed=true]{background:#dcefe2;border-color:#277b59}.stats{display:flex;gap:28px;flex-wrap:wrap;margin-top:12px}.stat strong{font-size:29px;display:block;color:var(--teal)}progress{width:100%;height:9px;accent-color:var(--teal)}.strip{background:#e9f2ed;border-radius:12px;padding:16px 20px;margin:18px 0}.choice{display:block;width:100%;text-align:left;margin:9px 0;white-space:normal}.choice[aria-pressed=true]{border:2px solid var(--teal)}.feedback{padding:13px;background:#eaf5ee;border-radius:8px;margin-top:14px}.feedback.wrong{background:#fff2e6}.scenario{margin-bottom:18px}textarea{min-height:100px;resize:vertical}.storyrow{margin:15px 0}.storyrow span{display:block;font-size:13px;color:var(--muted);margin-bottom:6px}.checkrow{display:flex;gap:12px;align-items:flex-start;border-bottom:1px solid #e3ebe5;padding:12px 0}.checkrow input{width:20px;height:20px;margin-top:4px;accent-color:var(--teal);flex-shrink:0}.checkrow:has(input:checked){color:#527768}.agenda{display:grid;grid-template-columns:70px 1fr;gap:16px;margin:15px 0}.agenda strong{color:var(--teal)}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#edf5f0}.scroll{overflow-x:auto}footer{font-size:12px;color:var(--muted);margin-top:26px;border-top:1px solid var(--line);padding-top:16px}.source{font-size:12px}.pill{font-size:12px;border-radius:20px;padding:4px 9px;background:#edf5f0;display:inline-block;margin-bottom:9px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}#announce{min-height:20px;font-size:13px;color:var(--teal)}@media(max-width:720px){.grid,.triple{grid-template-columns:1fr}header{padding:30px 22px}.shell{padding:18px 16px 40px}.card{padding:20px}.filters{grid-template-columns:1fr}nav{gap:3px}nav button{font-size:13px;padding:9px 10px}h2{font-size:23px}.intro{font-size:16px}}@media print{header{background:white;color:black;padding:0;border-bottom:2px solid black}header p,.badge{color:black}.shell{max-width:none;padding:0}nav,.actions,.review,button,.filters,#announce{display:none!important}section[hidden]{display:block}section{break-before:page}.card{break-inside:avoid}.grid,.triple{display:block}.card{margin:15px 0}details{break-inside:avoid}.body{display:block!important}footer{color:black}textarea{min-height:80px}}\n</style></head><body><header><div class="eyebrow overline">ANJANA\'S INTERVIEW GUIDE</div><h1>Your cardiac experience.<br>Your next CCU team.</h1><p>A focused preparation guide for NMC Healthcare, Abu Dhabi. Build clear answers around the work you actually did, then practise the clinical decisions behind them.</p><div class="badges"><span class="badge">Monday · 9 November 2026</span><span class="badge">9:30 a.m. · Abu Dhabi time</span><span class="badge">In person · CCU</span></div></header><main class="shell"><nav role="tablist" aria-label="Guide sections"><button role="tab" id="tab-start" aria-controls="start" aria-selected="true" data-tab="start">Start here</button><button role="tab" id="tab-clinical" aria-controls="clinical" aria-selected="false" data-tab="clinical">CCU essentials</button><button role="tab" id="tab-questions" aria-controls="questions" aria-selected="false" data-tab="questions">Answer guide</button><button role="tab" id="tab-scenarios" aria-controls="scenarios" aria-selected="false" data-tab="scenarios">Scenarios</button><button role="tab" id="tab-stories" aria-controls="stories" aria-selected="false" data-tab="stories">My examples</button><button role="tab" id="tab-day" aria-controls="day" aria-selected="false" data-tab="day">Interview day</button><button role="tab" id="tab-sources" aria-controls="sources" aria-selected="false" data-tab="sources">Sources</button></nav><div id="announce" role="status" aria-live="polite"></div>\n<section id="start" role="tabpanel"><div class="grid"><article class="card"><div class="eyebrow">START HERE</div><h2>You already have relevant experience.</h2><p><strong>2 years and 7 months in adult Cardiac ICU.</strong> A 15-bed unit, a usual 1:2 nurse-to-patient ratio and Backbone EMR. Make those facts the foundation of your answers.</p><p>Explain what you assessed, what changed, what you did within your role, who you called and how you reassessed.</p><div class="note">Your goal is to sound clear, safe and honest. You do not need to know everything or give a perfect speech.</div><div class="actions"><button class="primary" data-go="questions">Start with my introduction</button><button data-go="clinical">Review CCU essentials</button></div></article><article class="card"><div class="eyebrow">THE INTERVIEW</div><h2>Monday, 9:30 a.m.</h2><p>NMC Healthcare, Abu Dhabi · CCU · in person.</p><div class="note warm">The exact hospital branch and room are still to be confirmed. Check the invitation before planning your route. Abu Dhabi has several NMC facilities.</div><p class="small">Date interpreted from your confirmed Monday appointment as 9 November 2026. Follow the invitation if it differs.</p><div class="stats"><div class="stat"><strong id="readyCount">0</strong><span>answers ready aloud</span></div><div class="stat"><strong id="checkCount">0</strong><span>checklist items done</span></div></div><progress id="progress" max="25" value="0" aria-label="Questions ready aloud"></progress></article></div><div class="strip"><strong>The answer pattern</strong> · Assess → recognise risk → act within competence → escalate clearly → reassess → document.</div><div class="grid"><article class="card"><h3>A 90-minute first pass</h3><div class="agenda"><strong>15 min</strong><span>Introduction, why CCU, licence status and two genuine examples.</span></div><div class="agenda"><strong>30 min</strong><span>Chest pain, arrest rhythms, unstable tachycardia / bradycardia and post-PCI care.</span></div><div class="agenda"><strong>20 min</strong><span>Work through the six scenarios before revealing their explanations.</span></div><div class="agenda"><strong>15 min</strong><span>Medicines, communication and honest limits. Say answers aloud.</span></div><div class="agenda"><strong>10 min</strong><span>Documents, venue and questions for the panel.</span></div></article><article class="card"><h3>Use the remaining days well</h3><p><strong>Friday / Saturday</strong><br>Do the first pass. Mark uncertain answers. Write two real examples.</p><p><strong>Sunday</strong><br>Revisit weak topics, practise with someone asking follow-ups, check documents and rest.</p><p><strong>Monday morning</strong><br>Review your introduction and key distinctions. Leave early and aim for reception around 9:00–9:10 a.m., unless NMC instructed otherwise.</p></article></div></section>\n<section id="clinical" role="tabpanel" hidden><h2>CCU essentials to explain clearly</h2><p class="muted">Study prompts for interview preparation. Clinical practice must follow current hospital protocols, training and authorised orders.</p><div class="grid triple"><article class="card"><h3>Patient first</h3><p>Assess the patient, pulse and stability. Call for help early. State your actions, reassessment and communication.</p></article><article class="card"><h3>New chest pain</h3><p>Urgent assessment and escalation, observations and 12-lead ECG pathway. Oxygen is based on clinical need, not an automatic MONA sequence.</p></article><article class="card"><h3>Rhythm distinction</h3><p>VF / pulseless VT are shockable. PEA / asystole are not. A rhythm with a pulse is a different pathway.</p></article><article class="card"><h3>Post-PCI care</h3><p>Pain, observations, rhythm, access site, bleeding signs and distal perfusion. Explain care you actually performed.</p></article><article class="card"><h3>Heart failure / perfusion</h3><p>Connect breathlessness, fluid balance, urine-output trend, blood pressure and mental state. Escalate deterioration.</p></article><article class="card"><h3>Medicines and teamwork</h3><p>Know the checks, monitoring and escalation for medicines you actually administered. Use closed-loop communication and SBAR.</p></article></div><article class="card" style="margin-top:18px"><h3>Rhythm questions: keep the patient in the answer</h3><div class="scroll"><table><thead><tr><th>Finding</th><th>Key distinction to explain</th></tr></thead><tbody><tr><td>VF or pulseless VT</td><td>Cardiac arrest. Shockable rhythm. Activate emergency response and follow the arrest algorithm.</td></tr><tr><td>PEA or asystole</td><td>Cardiac arrest. Non-shockable rhythm. CPR, team response and reversible causes.</td></tr><tr><td>Tachycardia with a pulse</td><td>Assess whether the rhythm is causing clinical instability. Escalate and prepare clinician-led treatment.</td></tr><tr><td>Bradycardia with a pulse</td><td>Differentiate an isolated slow rate from poor perfusion and symptomatic compromise.</td></tr><tr><td>Monitor alarm</td><td>Assess the patient and verify the signal. Do not dismiss a dangerous finding as artefact without checking.</td></tr></tbody></table></div><p class="source">Review <a href="https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-advanced-life-support" target="_blank" rel="noopener">AHA adult advanced life support</a> and the linked algorithms in Sources.</p></article><div class="grid" style="margin-top:18px"><article class="card"><h3>Medicines: explain your checks</h3><p>For medicines you actually administered, rehearse the purpose, relevant observations and laboratory checks, important adverse effects, required independent checks, pump setup and escalation.</p><p>Common CCU areas to revise include antiplatelets, anticoagulants, nitrates, diuretics and rhythm-related treatment. Do not claim you administered a particular drug unless you did.</p><div class="note">If asked a dose you cannot recall confidently, do not guess. Explain how you verify the current protocol, prescription and concentration.</div></article><article class="card"><h3>Show what you know, and your limits</h3><p>“I have experience with post-PTCA nursing observations and care. I have not worked as a procedural Cath Lab nurse.”</p><p>“I would assess and escalate immediately, perform the actions within my competence and prepare the prescribed treatment.”</p><p>“I have not used your system yet. I used Backbone EMR and would complete orientation and competency assessment.”</p></article></div></section>\n<section id="questions" role="tabpanel" hidden><h2>Your answer guide</h2><p class="muted">Answer aloud first. Then open the guide. Use the structure and your own words.</p><div class="filters"><label>Find a topic<input id="search" type="search" placeholder="Chest pain, ECG, licence, medicines…"></label><label>Show<select id="filter"><option value="all">All questions</option><option value="clinical">Clinical and safety</option><option value="hr">Introduction and HR</option><option value="review">Needs review</option></select></label></div><p id="resultCount" class="small"></p><div id="questionList"></div></section>\n<section id="scenarios" role="tabpanel" hidden><h2>Think through six CCU situations</h2><p class="muted">These are practice scenarios, not NMC\'s actual questions. Choose a response, read the reasoning, then answer the follow-up aloud.</p><div id="scenarioList"></div></section>\n<section id="stories" role="tabpanel" hidden><h2>Two genuine examples are better than ten memorised stories.</h2><p>Use an actual event from Nirmala Hospital. Leave patient names, dates of birth, identifiers and other identifying details out. Do not invent observations or outcomes.</p><div class="grid"><article class="card"><h3>1 · Recognising deterioration</h3><p class="small">A change you noticed, your assessment and escalation, and how the team responded.</p><label class="storyrow">Situation<span>What was happening? Keep it anonymised.</span><textarea data-note="Example 1 - Situation" maxlength="1800"></textarea></label><label class="storyrow">My responsibility<span>What was your role at that moment?</span><textarea data-note="Example 1 - My responsibility" maxlength="1800"></textarea></label><label class="storyrow">What I noticed<span>Use only observations and numbers you actually remember.</span><textarea data-note="Example 1 - What I noticed" maxlength="1800"></textarea></label><label class="storyrow">What I did<span>Your assessment, actions, escalation and communication.</span><textarea data-note="Example 1 - What I did" maxlength="1800"></textarea></label><label class="storyrow">Outcome and learning<span>What you know happened, and what you learned.</span><textarea data-note="Example 1 - Outcome and learning" maxlength="1800"></textarea></label></article><article class="card"><h3>2 · Communication or medication safety</h3><p class="small">A genuine handover, concern you escalated, family discussion or safety check.</p><label class="storyrow">Situation<span>What was happening? Keep it anonymised.</span><textarea data-note="Example 2 - Situation" maxlength="1800"></textarea></label><label class="storyrow">My responsibility<span>What was your role at that moment?</span><textarea data-note="Example 2 - My responsibility" maxlength="1800"></textarea></label><label class="storyrow">What I noticed<span>Use only observations and numbers you actually remember.</span><textarea data-note="Example 2 - What I noticed" maxlength="1800"></textarea></label><label class="storyrow">What I did<span>Your assessment, actions, escalation and communication.</span><textarea data-note="Example 2 - What I did" maxlength="1800"></textarea></label><label class="storyrow">Outcome and learning<span>What you know happened, and what you learned.</span><textarea data-note="Example 2 - Outcome and learning" maxlength="1800"></textarea></label></article></div><div class="note" style="margin-top:18px">Use “I” for your own actions and “we” for the team\'s actions. If you do not know the final outcome, say so. Practise a 90-second version and a 30-second version.</div><div class="actions"><button id="exportNotes">Download my practice notes</button></div><p class="small">Notes and progress stay in this browser when storage is available. This guide does not send them to an AI service. Avoid shared devices for personal notes.</p></section>\n<section id="day" role="tabpanel" hidden><h2>Arrive prepared, not overloaded.</h2><div class="grid"><article class="card"><h3>Interview-day checklist</h3><div id="checklist"></div></article><article class="card"><h3>Five reminders at reception</h3><ol class="steps"><li>Introduce yourself with your name and the CCU appointment.</li><li>Take a moment before answering. Ask for clarification if needed.</li><li>Put patient assessment and safety before a list of tasks.</li><li>Use your actual experience and acknowledge limits.</li><li>Close by asking about orientation and next steps.</li></ol><h3 style="margin-top:25px">A clear closing</h3><p>“Thank you for meeting with me. My adult Cardiac ICU experience is closely related to this role, and I would welcome the opportunity to contribute and learn your unit\'s practices. May I ask about the next steps?”</p><div class="note warm">Bring documents for review. Do not describe eligibility as an activated licence or promise an authorised clinical start date before it is confirmed.</div></article></div></section>\n<section id="sources" role="tabpanel" hidden><h2>References and useful boundaries</h2><p>This is independent interview preparation. It is not an official NMC question bank, a clinical protocol or a prediction of selection.</p><div class="card"><h3>Clinical and employer references</h3><ul id="sourceList"></ul><p class="small">Links checked during preparation on 6 November 2026. Review the official algorithms for current details and use the employer\'s local policies in practice.</p></div><div class="card" style="margin-top:18px"><h3>Her factual baseline</h3><p>Nirmala Hospital, Kozhikode, Kerala, India · January 2024 to July 2026 · 2 years and 7 months as supplied · adult Cardiac ICU · 15-bed unit · usual ratio 1:2 · Backbone EMR · BSc Nursing · DOH eligibility · AHA BLS and ACLS.</p><p>No invented paediatric, OT, procedural Cath Lab, UAE employment or activated licence claims are included.</p></div></section><div class="actions"><button id="printGuide">Print / save guide as PDF</button><button id="resetProgress">Clear saved progress and notes</button></div><footer>Prepared for Anjana · NMC Healthcare, Abu Dhabi CCU interview · No voice mode, microphone, API key or AI subscription required.</footer></main><script>\nconst DATA={"questions": [{"id": "intro", "category": "Your introduction", "q": "Tell me about yourself in one minute.", "answer": "I am Anjana Anna Benny, a BSc-qualified Registered Nurse with 2 years and 7 months of adult Cardiac ICU experience at Nirmala Hospital in Kozhikode, Kerala, India. I worked in a 15-bed unit with a usual nurse-to-patient ratio of 1:2. My responsibilities included patient assessment, ECG monitoring, prescribed medicines and IV therapy, recognising deterioration and patient education. I used Backbone EMR for documentation. I hold DOH eligibility and AHA BLS and ACLS. I am interested in this CCU role because it builds directly on my cardiac nursing experience.", "focus": "Speak for 45–60 seconds. This is a structure to personalise, not a speech to recite.", "avoid": "Keep the duration accurate. DOH eligibility is not an activated licence. Use your own words rather than memorising every sentence.", "source": null}, {"id": "why", "category": "Your introduction", "q": "Why NMC and why CCU?", "answer": "CCU is closely aligned with my adult Cardiac ICU experience. NMC describes cardiology services in Abu Dhabi that include coronary disease, heart failure and arrhythmia care. I would like to contribute my assessment, ECG monitoring and escalation experience while learning the unit’s systems and protocols. I am particularly interested in the orientation and competencies expected in this CCU.", "focus": "Verify which NMC hospital invited you. Connect your own experience to the actual unit rather than claiming facts about an unconfirmed branch.", "avoid": "Do not claim that every NMC facility has the same services or quote an unverified accreditation.", "source": "hospital"}, {"id": "facts", "category": "Your introduction", "q": "What is your licence status and when can you join?", "answer": "I hold DOH eligibility as a Registered Nurse. My UAE professional licence has not been activated. I am immediately available for onboarding and will complete the employer’s licensing and credentialing requirements before starting clinical practice.", "focus": "Bring the eligibility document and answer consistently with it. Confirm the activation process with HR.", "avoid": "Do not say active DOH licence or promise a clinical start before authorisation.", "source": null}, {"id": "strength", "category": "Your introduction", "q": "What makes you a useful addition to our team?", "answer": "I bring recent adult Cardiac ICU experience, careful observation, timely escalation and reliable documentation. Caring for two patients in a 15-bed unit helped me organise priorities and communicate with the team. I can illustrate those strengths with a real example of recognising a change in a patient and requesting timely review.", "focus": "Follow this with one genuine example, not a list of adjectives.", "avoid": "Do not claim a measurable reduction in infections or mortality without evidence.", "source": null}, {"id": "leaving", "category": "Your introduction", "q": "Why did your previous employment end in July 2026?", "answer": "Prepare the actual reason in one calm sentence: “My employment ended in July 2026 because [true reason]. Since then I have [genuine activities]. I am now available for the next appropriate nursing role.” Keep the dates aligned with your experience certificate.", "focus": "Fill the brackets yourself. There is no verified reason in the information supplied.", "avoid": "Do not invent relocation dates, courses, family events or an explanation for the gap.", "source": null}, {"id": "weakness", "category": "Your introduction", "q": "What do you still need to develop?", "answer": "A new area for me is working within Dubai-specific hospital systems and policies. I would address this by completing orientation, reviewing local pathways, asking for feedback and demonstrating competencies under supervision. Choose another genuine development need if this does not reflect your experience.", "focus": "Name a specific limitation and a practical plan.", "avoid": "Avoid pretending perfection or using a safety-critical knowledge gap as a casual weakness.", "source": null}, {"id": "salary", "category": "Your introduction", "q": "What salary do you expect? Can you work shifts?", "answer": "I am open to discussing the approved package for the role, including the roster, allowances, insurance and professional development. Could you share the range? State honestly whether you can work nights, weekends and rotating shifts, and when you can relocate if required.", "focus": "Decide your actual minimum and practical commitments privately before the interview.", "avoid": "Do not agree to conditions you cannot meet or invent a salary benchmark.", "source": null}, {"id": "chest", "category": "Cardiac and emergency", "q": "A patient develops new chest pain. How do you respond?", "answer": "I take the symptom seriously, assess promptly and activate the appropriate urgent review. I obtain observations and a 12-lead ECG according to protocol, report onset and associated symptoms, and prepare prescribed investigations and treatment. I assess oxygen need rather than give it routinely. A normal initial ECG does not by itself exclude an acute coronary syndrome.", "focus": "Keep assessment, early escalation and reassessment central. Check contraindications before prescribed medicines.", "avoid": "Do not dismiss pain as anxiety or recite MONA as an automatic treatment order.", "source": "chest"}, {"id": "arrest", "category": "Cardiac and emergency", "q": "Which rhythms are shockable during adult cardiac arrest?", "answer": "Ventricular fibrillation and pulseless ventricular tachycardia are shockable. Asystole and pulseless electrical activity are not. I support CPR, defibrillator use when indicated, assigned code-team tasks and investigation of reversible causes. After a shock, CPR resumes promptly as directed by the algorithm.", "focus": "Confirm the patient’s condition and pulse status, not only the rhythm label.", "avoid": "Do not shock asystole or confuse pulseless VT with VT that has a pulse.", "source": "arrest"}, {"id": "tachy", "category": "Cardiac and emergency", "q": "A patient has tachycardia and hypotension. What matters first?", "answer": "I assess pulse and clinical stability, summon urgent help and support monitoring and ABCs. Hypotension, altered mental status, shock, ischaemic discomfort or acute heart failure may indicate instability caused by the rhythm. I prepare for the clinician-led treatment, which may include synchronised cardioversion, with sedation when feasible. Polymorphic VT requires a different shock approach.", "focus": "A patient with no pulse follows the cardiac arrest pathway. Explain this distinction.", "avoid": "Do not give adenosine indiscriminately for every fast or wide-complex rhythm.", "source": "tachy"}, {"id": "brady", "category": "Cardiac and emergency", "q": "A patient has bradycardia with dizziness and low blood pressure.", "answer": "I assess perfusion, activate urgent help and support airway, breathing, monitoring and access. I prepare clinician-directed treatment following the current bradycardia algorithm. Persistent compromise may require medication and pacing support. I report possible reversible causes and reassess the response.", "focus": "Explain the difference between a slow rate alone and symptomatic compromise.", "avoid": "Do not wait for routine review when the patient is unstable or guess medicine doses.", "source": "brady"}, {"id": "postpci", "category": "Cardiac and emergency", "q": "What do you watch for after a coronary intervention?", "answer": "I follow the prescribed post-procedure plan, monitoring observations, rhythm, pain and the access site. I assess for bleeding, swelling and changes in distal perfusion, and urgently report recurrent chest pain, deterioration or suspected bleeding. I check prescribed medicines and patient education. I distinguish this nursing follow-up from working inside the Cath Lab.", "focus": "Use only the post-PTCA observations and care you actually performed.", "avoid": "Do not claim independent sheath removal, procedural Cath Lab experience or decisions to stop antiplatelets.", "source": null}, {"id": "shock", "category": "Assessment and ICU", "q": "How do you recognise poor perfusion or shock?", "answer": "I look at trends in blood pressure, mental status, skin perfusion, urine output and the overall clinical picture. I escalate deterioration promptly and report relevant symptoms, losses, cardiac history and available investigations. I follow the prescribed monitoring and treatment plan and reassess the response rather than relying on one reading.", "focus": "Distinguish recognising shock from deciding its cause and prescribing treatment.", "avoid": "Do not give every hypotensive patient an unassessed fluid bolus, especially with cardiac failure.", "source": null}, {"id": "balance", "category": "Assessment and ICU", "q": "How do you monitor fluid balance in a cardiac patient?", "answer": "I record intake and output accurately, follow urine-output trends and prescribed weights, and assess oedema, breathlessness and observations. I check relevant treatments and available results, communicate changes and reassess after prescribed interventions. If urine output falls I assess the patient and check for practical collection problems within policy, while arranging review.", "focus": "Give a real example of what you documented in Backbone EMR.", "avoid": "Do not assume reduced urine output always means dehydration.", "source": null}, {"id": "abcde", "category": "Assessment and ICU", "q": "How do you approach a deteriorating patient?", "answer": "I assess immediate danger and call for appropriate help early. I use ABCDE, addressing life-threatening problems as I find them. I reassess after interventions, work with the team and communicate the changes and urgency using SBAR. I document observations, actions and the response.", "focus": "Say what you would assess, not just the letters. Airway, Breathing, Circulation, Disability, Exposure.", "avoid": "Do not finish a long history before responding to an immediate threat.", "source": "abcde"}, {"id": "handover", "category": "Assessment and ICU", "q": "Give an SBAR escalation for a deteriorating patient.", "answer": "Use this hypothetical structure. Situation: “I need urgent review of a patient with new breathlessness and falling blood pressure.” Background: diagnosis, relevant treatment and baseline. Assessment: actual observations, trend and actions taken. Recommendation: request immediate review and clarify the monitoring and treatment plan. Read back key instructions and confirm who is coming.", "focus": "In a real interview example, use only numbers you remember accurately.", "avoid": "Do not present the hypothetical case as an event from your employment.", "source": null}, {"id": "meds", "category": "Safety and teamwork", "q": "How do you administer a high-risk medicine safely?", "answer": "I verify the patient using approved identifiers, the prescription, allergies, medicine, dose, route, timing and relevant clinical checks. I calculate carefully, follow required independent-check and pump policies, and monitor the response. If something is unclear or inconsistent, I pause and clarify with the prescriber or pharmacist before administration.", "focus": "Explain the checks you genuinely used for IV medicines and infusion pumps.", "avoid": "Do not rely on memory alone or assume a colleague’s calculation must be correct.", "source": null}, {"id": "error", "category": "Safety and teamwork", "q": "You discover a medication error. What do you do?", "answer": "I protect the patient first, stop the unsafe process as appropriate, assess and promptly notify the senior nurse and prescriber. I follow monitoring and treatment instructions, document the facts and complete the incident process. I support honest disclosure through the hospital’s policy and contribute to learning and prevention.", "focus": "Near misses also deserve reporting. Use a real example only if you have one.", "avoid": "Never hide the error, alter the record to conceal it or blame colleagues.", "source": null}, {"id": "infection", "category": "Safety and teamwork", "q": "How do you reduce infection risks?", "answer": "I perform hand hygiene at the appropriate care moments, use PPE based on risk and apply aseptic technique. I follow device-care and isolation policies, keep equipment and the care environment safe, and report concerns. Gloves do not replace hand hygiene. Device necessity and signs of infection require ongoing review with the team.", "focus": "Be ready to describe one task, such as IV care, in practical terms.", "avoid": "Do not claim zero infections or use gloves as a substitute for cleaning hands.", "source": "infection"}, {"id": "family", "category": "Safety and teamwork", "q": "A family member is angry about a delay. What do you say?", "answer": "I acknowledge the concern, listen and explain what I can accurately share in clear language. I avoid promises about a time I cannot control. I check immediate needs, update the responsible team and seek senior support if necessary. I protect confidentiality and use approved interpretation when needed.", "focus": "Try: “I can see this delay is worrying. Let me check the current plan and update you.”", "avoid": "Do not argue, blame another department or share another patient’s information.", "source": null}, {"id": "refusal", "category": "Safety and teamwork", "q": "A patient refuses treatment.", "answer": "I listen to the reason, check understanding and explain the proposed care in accessible language. I assess immediate safety, notify the responsible clinician and senior nurse, document accurately and follow consent and capacity processes. I respect the person’s dignity and seek authorised support if there are concerns about decision-making ability.", "focus": "Follow UAE requirements and hospital policy. A refusal is not permission to use force.", "avoid": "Do not conceal medication in food or independently override a refusal.", "source": null}, {"id": "story", "category": "Safety and teamwork", "q": "Tell us about a time you recognised deterioration.", "answer": "Choose an actual anonymised ICU event. Describe the situation, your responsibility, the specific change you noticed, what you assessed and escalated, and what happened next. Explain your own contribution without taking credit for the team. If the final outcome is unknown, say so. End with what you learned.", "focus": "Use the real-story builder. Prepare a 90-second version and a 30-second version.", "avoid": "Do not invent numbers, dramatic rescues or patient outcomes.", "source": null}, {"id": "conflict", "category": "Safety and teamwork", "q": "What if a colleague dismisses your safety concern?", "answer": "I calmly state the specific concern and the risk, give the observations and request review. If the issue remains unresolved and the patient may be unsafe, I use the escalation chain promptly. I communicate respectfully, keep factual records and reflect with the team afterwards.", "focus": "Show that respect and assertive escalation can coexist.", "avoid": "Do not remain silent to avoid conflict or turn the answer into a complaint about a past colleague.", "source": null}, {"id": "unknown", "category": "Safety and teamwork", "q": "What if you are asked to perform an unfamiliar procedure?", "answer": "I explain my current competence, ensure immediate patient safety and request a competent colleague’s support. I use the approved training and supervised competency pathway before independent practice. In an emergency I call for help and contribute the actions for which I am trained.", "focus": "This is especially important for unfamiliar equipment, CRRT, ECMO, IABP, OT or paediatrics.", "avoid": "Do not claim competencies just because the unit uses the equipment.", "source": null}, {"id": "questions", "category": "Safety and teamwork", "q": "What would you ask at the end of the interview?", "answer": "What are the main patient groups and nurse responsibilities in this CCU? How is orientation arranged for a nurse joining from overseas experience? Which competencies do you assess during probation? What are the next recruitment and licensing steps?", "focus": "Choose two or three. Listen carefully to what the interviewer has already explained.", "avoid": "Do not ask only about pay and leave, and do not assume this is an offer.", "source": null}], "sources": {"abcde": ["Resuscitation Council UK: ABCDE approach", "https://www.resus.org.uk/library/abcde-approach"], "bls": ["AHA 2025: adult basic life support", "https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support"], "arrest": ["AHA 2025: adult cardiac arrest algorithm", "https://cpr.heart.org/-/media/CPR-Files/CPR-Guidelines-Files/2025-Accessible/Algorithm-ACLS-CA-LngDscrp-250725-Ed.pdf"], "tachy": ["AHA 2025: tachyarrhythmia with a pulse", "https://cpr.heart.org/-/media/CPR-Files/CPR-Guidelines-Files/2025-Algorithms/Algorithm-ACLS-Tachycardia-250514.pdf"], "brady": ["AHA 2025: bradycardia with a pulse", "https://cpr.heart.org/-/media/CPR-Files/CPR-Guidelines-Files/2025-Accessible/Algorithm-ACLS-Bradycardia-LngDscrp-250725-Ed.pdf"], "chest": ["NICE CG95: suspected cardiac chest pain", "https://www.nice.org.uk/guidance/CG95/chapter/recommendations"], "infection": ["CDC: core infection prevention practices", "https://www.cdc.gov/infection-control/hcp/core-practices/"], "hospital": ["NMC: cardiology services in Abu Dhabi", "https://nmc.ae/en/locations/abu-dhabi/cardiology"], "acs": ["ESC: acute coronary syndrome guideline", "https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes"], "als": ["AHA: adult advanced life support", "https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-advanced-life-support"]}, "scenarios": [{"title": "Chest pain in CCU", "case": "A patient reports new chest pressure and sweating. What is your first response?", "options": ["Wait for the next routine observation round", "Assess promptly, obtain observations, activate urgent review and follow the ECG pathway", "Reassure the patient because the last ECG was normal"], "correct": 1, "explain": "Begin with the patient and urgency. Explain assessment, observations, timely escalation, ECG according to protocol and reassessment. A previous or initial normal ECG does not rule out ACS.", "follow": "What would you report in your SBAR call?", "source": "chest"}, {"title": "A fast rhythm and low blood pressure", "case": "The monitor shows a fast broad-complex rhythm. The patient is dizzy and hypotensive. What distinction must you establish immediately?", "options": ["Whether the patient has a pulse and is clinically unstable", "Whether the monitor paper has been printed", "Whether the patient had lunch"], "correct": 0, "explain": "Pulse status and clinical stability determine the emergency pathway. Pulseless VT is an arrest rhythm; a tachyarrhythmia with a pulse requires assessment for instability and urgent clinician-led treatment.", "follow": "How does your response change if the patient becomes unresponsive and pulseless?", "source": "tachy"}, {"title": "Post-PCI deterioration", "case": "After coronary intervention, a patient becomes pale and hypotensive and reports new pain. The access-site dressing looks dry. What is the safest reasoning?", "options": ["A dry dressing excludes bleeding", "Assume anxiety and reassess later", "Assess and escalate urgently; consider complications even without visible external bleeding"], "correct": 2, "explain": "Do not let one reassuring finding replace assessment. Describe monitoring, access-site and distal-perfusion checks within policy, pain assessment, urgent escalation and reassessment. Do not independently stop prescribed antiplatelets.", "follow": "Which observations and recent treatments would you communicate?", "source": "acs"}, {"title": "Falling urine output", "case": "A cardiac patient has reduced urine output and increasing breathlessness. Which answer shows safer reasoning?", "options": ["Give a fluid bolus automatically", "Assess the patient, review trends and collection issues, and request clinical review", "Ignore output if the blood pressure is normal"], "correct": 1, "explain": "Reduced urine output is not proof of dehydration. Review the whole picture, prescribed fluid plan, relevant observations and trends, then escalate. Avoid unassessed fluid administration in a patient who may be congested.", "follow": "How would you describe your fluid-balance documentation?", "source": "abcde"}, {"title": "Asystole on the monitor", "case": "The patient is unresponsive, not breathing normally and has no definite pulse. The monitor shows asystole. What should your answer emphasise?", "options": ["Immediate defibrillation for every arrest rhythm", "Wait for the consultant before taking action", "Activate the emergency response and provide high-quality CPR; asystole is non-shockable"], "correct": 2, "explain": "VF and pulseless VT are shockable. Asystole and PEA are non-shockable. Follow the current resuscitation algorithm and your assigned role. Check the patient, not just the monitor.", "follow": "What are your nursing responsibilities within the code team?", "source": "arrest"}, {"title": "An unclear high-risk infusion", "case": "A prescribed infusion concentration does not match the pump setup or local protocol. What do you do?", "options": ["Use the previous shift’s rate without checking", "Pause and clarify the discrepancy before administration, with appropriate escalation", "Estimate the concentration from memory"], "correct": 1, "explain": "Explain patient identification, prescription and concentration checks, required independent checks, pump policy and clinical monitoring. If an infusion is already running, urgently escalate and follow the immediate safety response for that medicine and situation.", "follow": "How would you communicate and document a suspected medication error?", "source": null}], "checks": ["Confirm the exact NMC hospital, building, interview room and contact person", "Confirm Monday 9 November, 9:30 a.m. Abu Dhabi time against the invitation", "Plan travel and aim to reach reception around 9:00–9:10 a.m. unless instructed otherwise", "Carry 3 clean CV copies with the correct phone number", "Bring the invitation, DOH eligibility, nursing registration and BLS/ACLS evidence", "Bring degree and experience documents, plus identification if requested", "Prepare two genuine anonymised examples and a 45–60 second introduction", "Choose professional clothing, a pen and a small notebook", "Charge the phone, save the contact number and silence notifications", "Review only key reminders on the morning; allow time for breakfast and rest"]};\nconst KEY=\'anjana-nmc-ccu-guide-v1\';let saved={ready:{},checks:{},notes:{},scenarios:{}};\ntry{saved={...saved,...JSON.parse(localStorage.getItem(KEY)||\'{}\')};}catch{}\nconst $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nfunction persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{$(\'announce\').textContent=\'Browser storage is unavailable. Download your notes before leaving.\';}stats();}\nfunction stats(){$(\'readyCount\').textContent=Object.values(saved.ready).filter(Boolean).length;$(\'progress\').value=Number($(\'readyCount\').textContent);$(\'checkCount\').textContent=Object.values(saved.checks).filter(Boolean).length;}\nfunction go(id){document.querySelectorAll(\'main>section\').forEach(x=>x.hidden=x.id!==id);document.querySelectorAll(\'[role=tab]\').forEach(x=>{x.setAttribute(\'aria-selected\',x.dataset.tab===id);x.tabIndex=x.dataset.tab===id?0:-1;});if(id===\'questions\')renderQuestions();$(\'announce\').textContent=\'\';}\ndocument.querySelectorAll(\'[role=tab]\').forEach(b=>{b.onclick=()=>go(b.dataset.tab);b.onkeydown=e=>{const tabs=[...document.querySelectorAll(\'[role=tab]\')];let i=tabs.indexOf(b);if([\'ArrowRight\',\'ArrowLeft\',\'Home\',\'End\'].includes(e.key)){e.preventDefault();i=e.key===\'Home\'?0:e.key===\'End\'?tabs.length-1:(i+(e.key===\'ArrowRight\'?1:-1)+tabs.length)%tabs.length;go(tabs[i].dataset.tab);tabs[i].focus();}};});document.querySelectorAll(\'[data-go]\').forEach(b=>b.onclick=()=>go(b.dataset.go));\nfunction source(key){const s=DATA.sources[key];return s?`<p class="source">Reference · <a href="${esc(s[1])}" target="_blank" rel="noopener">${esc(s[0])}</a></p>`:\'\';}\nfunction renderQuestions(){let term=$(\'search\').value.toLowerCase(),filter=$(\'filter\').value;const hr=[\'intro\',\'why\',\'facts\',\'strength\',\'leaving\',\'weakness\',\'salary\',\'questions\'];const items=DATA.questions.filter(q=>JSON.stringify(q).toLowerCase().includes(term)&&(filter===\'all\'||filter===\'review\'&&!saved.ready[q.id]||filter===\'hr\'&&hr.includes(q.id)||filter===\'clinical\'&&!hr.includes(q.id)));$(\'resultCount\').textContent=items.length+\' questions\';$(\'questionList\').innerHTML=items.map(q=>`<details id="q-${q.id}"><summary><span class="qnum">${String(DATA.questions.indexOf(q)+1).padStart(2,\'0\')}</span>${esc(q.q)}</summary><div class="body"><p class="answer">${esc(q.answer)}</p><div class="note">${esc(q.focus)}</div><p class="small"><strong>Avoid</strong> · ${esc(q.avoid)}</p>${source(q.source)}<div class="review"><button data-ready="${q.id}" aria-pressed="${!!saved.ready[q.id]}">${saved.ready[q.id]?\'✓ Ready aloud\':\'Mark ready aloud\'}</button></div></div></details>`).join(\'\');document.querySelectorAll(\'[data-ready]\').forEach(b=>b.onclick=()=>{saved.ready[b.dataset.ready]=!saved.ready[b.dataset.ready];b.setAttribute(\'aria-pressed\',!!saved.ready[b.dataset.ready]);b.textContent=saved.ready[b.dataset.ready]?\'✓ Ready aloud\':\'Mark ready aloud\';persist();});}\n$(\'search\').oninput=renderQuestions;$(\'filter\').onchange=renderQuestions;\nfunction renderScenarios(){$(\'scenarioList\').innerHTML=DATA.scenarios.map((s,i)=>{let picked=saved.scenarios[i];let answered=Number.isInteger(picked);return `<article class="card scenario"><span class="pill">Scenario ${i+1}</span><h3>${esc(s.title)}</h3><p>${esc(s.case)}</p>${s.options.map((o,j)=>`<button class="choice" data-case="${i}" data-option="${j}" aria-pressed="${picked===j}">${esc(o)}</button>`).join(\'\')}${answered?`<div class="feedback ${picked!==s.correct?\'wrong\':\'\'}"><strong>${picked===s.correct?\'That is the safer reasoning.\':\'Reconsider the priority.\'}</strong><p>${esc(s.explain)}</p><strong>Follow-up to answer aloud</strong><p>${esc(s.follow)}</p>${source(s.source)}</div>`:\'\'}</article>`}).join(\'\');document.querySelectorAll(\'[data-case]\').forEach(b=>b.onclick=()=>{saved.scenarios[b.dataset.case]=Number(b.dataset.option);persist();renderScenarios();});}\n$(\'checklist\').innerHTML=DATA.checks.map((c,i)=>`<label class="checkrow"><input type="checkbox" data-check="${i}" ${saved.checks[i]?\'checked\':\'\'}><span>${esc(c)}</span></label>`).join(\'\');document.querySelectorAll(\'[data-check]\').forEach(x=>x.onchange=()=>{saved.checks[x.dataset.check]=x.checked;persist();});\ndocument.querySelectorAll(\'[data-note]\').forEach(x=>{x.value=saved.notes[x.dataset.note]||\'\';x.oninput=()=>{saved.notes[x.dataset.note]=x.value;persist();};});\n$(\'sourceList\').innerHTML=Object.values(DATA.sources).map(s=>`<li><a href="${esc(s[1])}" target="_blank" rel="noopener">${esc(s[0])}</a></li>`).join(\'\');\n$(\'exportNotes\').onclick=()=>{const text=\'NMC CCU INTERVIEW PRACTICE\\nMonday 9 November 2026, 9:30 a.m. Abu Dhabi\\n\\n\'+Object.entries(saved.notes).map(([k,v])=>k+\'\\n\'+v).join(\'\\n\\n\');const u=URL.createObjectURL(new Blob([text],{type:\'text/plain\'}));const a=document.createElement(\'a\');a.href=u;a.download=\'Anjana_NMC_CCU_Practice_Notes.txt\';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};\n$(\'printGuide\').onclick=()=>{document.querySelectorAll(\'details\').forEach(x=>x.open=true);window.print();};\n$(\'resetProgress\').onclick=()=>{if(confirm(\'Clear the progress and notes saved by this guide in this browser?\')){saved={ready:{},checks:{},notes:{},scenarios:{}};persist();renderQuestions();renderScenarios();document.querySelectorAll(\'[data-note]\').forEach(x=>x.value=\'\');document.querySelectorAll(\'[data-check]\').forEach(x=>x.checked=false);$(\'announce\').textContent=\'Saved progress and notes cleared.\';}};\nstats();renderQuestions();renderScenarios();go(\'start\');\n</script></body></html>'
st.iframe(HTML, height="content", alt="Anjana NMC Abu Dhabi CCU interview guide")
